def transform(grid):
    """Restore 2-valued occlusions by bilateral reflection where possible."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                candidates = [grid[r][w-1-c], grid[h-1-r][c], grid[h-1-r][w-1-c]]
                known = [v for v in candidates if v != 2]
                if known:
                    out[r][c] = known[0]
                else:
                    out[r][c] = grid[c][r]
    return out
